ALTER TABLE public.profiles ADD COLUMN last_seen_at timestamptz;
CREATE FUNCTION public.touch_last_seen() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.profiles SET last_seen_at=now() WHERE id=auth.uid() AND public.account_can_write(); $$;
REVOKE ALL ON FUNCTION public.touch_last_seen() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.touch_last_seen() TO authenticated;
CREATE TABLE public.user_blocks (blocker_id uuid NOT NULL REFERENCES public.profiles(id), blocked_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
GRANT SELECT,INSERT,DELETE ON public.user_blocks TO authenticated; GRANT ALL ON public.user_blocks TO service_role;
ALTER TABLE public.user_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_blocks ON public.user_blocks FOR SELECT TO authenticated USING (blocker_id=auth.uid() AND public.account_can_read());
CREATE POLICY create_own_blocks ON public.user_blocks FOR INSERT TO authenticated WITH CHECK(blocker_id=auth.uid() AND public.account_can_write());
CREATE POLICY remove_own_blocks ON public.user_blocks FOR DELETE TO authenticated USING(blocker_id=auth.uid() AND public.account_can_write());
CREATE FUNCTION public.chat_is_blocked(p_conversation uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.conversations c JOIN public.conversation_members m ON m.conversation_id=c.id JOIN public.user_blocks b ON ((b.blocker_id=auth.uid() AND b.blocked_id=m.user_id) OR (b.blocked_id=auth.uid() AND b.blocker_id=m.user_id)) WHERE c.id=p_conversation AND c.type='dm' AND public.is_conversation_member(c.id,auth.uid())); $$;
REVOKE ALL ON FUNCTION public.chat_is_blocked(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.chat_is_blocked(uuid) TO authenticated;
CREATE POLICY block_direct_messages ON public.messages AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(NOT public.chat_is_blocked(conversation_id));
CREATE TABLE public.chat_clears (conversation_id uuid NOT NULL REFERENCES public.conversations(id),user_id uuid NOT NULL REFERENCES public.profiles(id),cleared_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(conversation_id,user_id));
GRANT SELECT ON public.chat_clears TO authenticated; GRANT ALL ON public.chat_clears TO service_role;
ALTER TABLE public.chat_clears ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_clear ON public.chat_clears FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.account_can_read());
CREATE FUNCTION public.clear_chat(p_conversation uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_can_write() OR NOT public.is_conversation_member(p_conversation,auth.uid()) THEN RAISE EXCEPTION 'Not allowed'; END IF; INSERT INTO public.chat_clears(conversation_id,user_id,cleared_at) VALUES(p_conversation,auth.uid(),now()) ON CONFLICT(conversation_id,user_id) DO UPDATE SET cleared_at=excluded.cleared_at; END; $$;
REVOKE ALL ON FUNCTION public.clear_chat(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.clear_chat(uuid) TO authenticated;
CREATE POLICY cleared_history ON public.messages AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT EXISTS(SELECT 1 FROM public.chat_clears c WHERE c.conversation_id=messages.conversation_id AND c.user_id=auth.uid() AND messages.created_at<=c.cleared_at));
CREATE TABLE public.user_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES public.profiles(id),reported_id uuid NOT NULL REFERENCES public.profiles(id),conversation_id uuid NOT NULL REFERENCES public.conversations(id),reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),CHECK(reporter_id<>reported_id));
GRANT SELECT,INSERT ON public.user_reports TO authenticated; GRANT ALL ON public.user_reports TO service_role;
ALTER TABLE public.user_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_chat_member ON public.user_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND public.account_can_write() AND public.is_conversation_member(conversation_id,auth.uid()) AND public.is_conversation_member(conversation_id,reported_id));
CREATE POLICY read_own_report ON public.user_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() AND public.account_can_read());